1	package main
2	
3	// End-to-end regression coverage for `suppressions register` over an archive
4	// whose stored report carries a decayed rule-version declaration: the whole
5	// registration must fail with exit code 1, no result JSON on stdout, an
6	// error naming the chain, block and the problem, and no change to the
7	// archive — no condition is added and the damaged declaration is left
8	// exactly as it was. Both intake paths (a spec file and standard input)
9	// fail identically, and over an intact archive both paths still register.
10	
11	import (
12		"encoding/json"
13		"os"
14		"path/filepath"
15		"strings"
16		"testing"
17	)
18	
19	// cliRegisterSpec is a legal condition that would cover 0xok but never the
20	// empty 0xdecayed report — which still has to be opened by the proof.
21	const cliRegisterSpec = `{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":0,"endHeight":100,"reason":"known bot war"}`
22	
23	// setupCorruptRegisterCLIArchive archives two blocks on chain "1" — 0xok at
24	// height 10 with a sandwich conclusion, 0xdecayed at height 20 with no
25	// swaps — then rewrites 0xdecayed's embedded version declaration to null
26	// and deletes the source input file. No condition is registered beforehand:
27	// the registration under test would be the archive's first.
28	func setupCorruptRegisterCLIArchive(t *testing.T) string {
29		t.Helper()
30		dir := t.TempDir()
31		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
32		lines := cliBlockLine("1", "0xok", 10,
33			cliSwapRecord("0xf", "p1", "bot", 90, 0),
34			cliSwapRecord("0xv", "p1", "user", 10, 1),
35			cliSwapRecord("0+k", "p1", "bot", 80, 2),
36		) + "\n" + `{"chainId":"1","blockHash":"0xdecayed","blockNumber":20,"swaps":[]}` + "\n"
37		if err := os.WriteFile(inputPath, []byte(lines), 0o644); err != nil {
38			t.Fatal(err)
39		}
40		if res := runCLI(t, "replay", inputPath, dir); res.exitCode != 0 {
41			t.Fatalf("replay exit=%d stderr=%q", res.exitCode, res.stderr)
42		}
43		if err := os.Remove(inputPath); err != nil {
44			t.Fatal(err)
45		}
46	
47		path := filepath.Join(dir, "archive.json")
48		raw, err := os.ReadFile(path)
49		if err != nil {
