51		}
52		var doc map[string]any
53		if err := json.Unmarshal(raw, &doc); err != nil {
54			t.Fatal(err)
55		}
56		for _, r := range doc["records"].([]any) {
57			rec := r.(map[string]any)
58			if rec["blockHash"] == "0xdecayed" {
59				rec["version"] = nil
60			}
61		}
62		out, err := json.MarshalIndent(doc, "", "  ")
63		if err != nil {
64			t.Fatal(err)
65		}
66		if err := os.WriteFile(path, out, 0o644); err != nil {
