142	// TestCLISuppressionsRegisterIntactArchive pins the unchanged success path
143	// for both intake paths: a spec file and then standard input each append
144	// their condition, print created:true with the full condition carrying
145	// revoked:false, and the second registration of identical content is a
146	// created:false no-op that leaves the revoked state untouched after a
147	// revocation.
148	func TestCLISuppressionsRegisterIntactArchive(t *testing.T) {
