1	package mevwatch
2	
3	// Regression coverage for enabling a rule version whose stored archive
4	// document has decayed since registration. `rules enable` must validate the
5	// selected version's actual stored declaration before it moves the enabled
6	// marker — the same proof a comparison, a review-range evaluation and a
7	// replay already demand — so a corrupt registered version is refused with
8	// ErrCorruptVersion (never reported unknown, never substituted with the
9	// current, built-in or default parameters), even when it is already the
10	// enabled version. A successful switch changes only the enabled marker:
11	// the other versions (corrupt siblings included), their fields and order,
12	// plus reports, suppressions, alert records and reviews are preserved.
13	
14	import (
15		"encoding/json"
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"syscall"
22		"testing"
23	)
24	
25	// enableSkeleton reads the archive the way EnableVersion writes it:
26	// versions stay raw stored documents, so the sections can be compared
27	// byte for byte across a successful switch.
28	type enableSkeleton struct {
29		Records        []record           `json:"records"`
30		Versions       []json.RawMessage  `json:"versions"`
31		EnabledVersion string             `json:"enabledVersion"`
32		Suppressions   []Suppression      `json:"suppressions"`
33		AlertRecords   []ProcessingRecord `json:"alerts"`
34		Reviews        []ReviewObject     `json:"reviews"`
35	}
36	
37	func readEnableSkeleton(t *testing.T, dir string) enableSkeleton {
38		t.Helper()
39		var s enableSkeleton
40		if err := json.Unmarshal(readArchiveFile(t, dir), &s); err != nil {
41			t.Fatal(err)
42		}
43		return s
44	}
45	
46	// TestEnableCorruptVersionRefused runs the full corruption matrix against
47	// enabling a registered version: every way its stored document can stop
48	// satisfying the registration rules must fail with ErrCorruptVersion, name
49	// the version and the offending rule or field, and leave the archive —
50	// including the enabled marker — untouched.
51	func TestEnableCorruptVersionRefused(t *testing.T) {
52		for _, tc := range corruptVersionCases {
53			t.Run(tc.name, func(t *testing.T) {
54				dir := setupCorruptCompareArchive(t)
55				if _, err := EnableVersion(dir, "twin"); err != nil {
56					t.Fatalf("setup: EnableVersion twin: %v", err)
57				}
58				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
59					tc.mutate(t, ver)
60				})
61				before := readArchiveFile(t, dir)
62	
63				v, err := EnableVersion(dir, "candC")
64				if err == nil {
65					t.Fatalf("corrupt version enabled successfully: %+v", v)
66				}
67				if !errors.Is(err, ErrCorruptVersion) {
68					t.Fatalf("error = %v, want ErrCorruptVersion", err)
69				}
70				if errors.Is(err, ErrUnknownVersion) {
71					t.Fatalf("registered-but-corrupt version misreported as unknown: %v", err)
72				}
73				if !strings.Contains(err.Error(), "candC") {
74					t.Fatalf("error must name the selected version, got %v", err)
75				}
76				if !strings.Contains(err.Error(), tc.wantErr) {
77					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
78				}
79				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
80					t.Fatalf("refused enable changed the archive:\nbefore=%s\nafter =%s", before, after)
81				}
82				if got := readEnableSkeleton(t, dir).EnabledVersion; got != "twin" {
83					t.Fatalf("enabled marker changed to %q on refusal", got)
84				}
85			})
86		}
87	}
88	
89	// TestEnableCorruptAlreadyEnabledRefused pins the core regression: the
90	// integrity check runs even when the selected id is already the current
91	// enabled version. Previously the early return accepted the decayed
92	// document as a complete version and left replay to fail later.
93	func TestEnableCorruptAlreadyEnabledRefused(t *testing.T) {
94		for _, tc := range corruptVersionCases {
95			t.Run(tc.name, func(t *testing.T) {
96				dir := setupCorruptCompareArchive(t)
97				if _, err := EnableVersion(dir, "candC"); err != nil {
98					t.Fatalf("setup: EnableVersion candC: %v", err)
99				}
100				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
101					tc.mutate(t, ver)
102				})
103				before := readArchiveFile(t, dir)
104	
105				v, err := EnableVersion(dir, "candC")
106				if !errors.Is(err, ErrCorruptVersion) {
107					t.Fatalf("re-enabling the corrupt enabled version: v=%+v err=%v, want ErrCorruptVersion", v, err)
108				}
109				if errors.Is(err, ErrUnknownVersion) {
110					t.Fatalf("corrupt enabled version misreported as unknown: %v", err)
111				}
112				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), tc.wantErr) {
113					t.Fatalf("error must name version candC and field %q, got %v", tc.wantErr, err)
114				}
115				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
116					t.Fatalf("refused re-enable changed the archive")
117				}
118				if got := readEnableSkeleton(t, dir).EnabledVersion; got != "candC" {
119					t.Fatalf("enabled marker changed on refusal: %q", got)
120				}
121			})
122		}
123	}
124	
125	// TestEnableCorruptSiblingDoesNotBlock proves damage in one registered
126	// version neither blocks enabling an intact sibling or builtin, nor gets
127	// repaired, completed, reordered or dropped by the successful switch: the
128	// versions section survives entry for entry, in order, and the corrupt
129	// entry is still afterwards refused on its own merits.
130	func TestEnableCorruptSiblingDoesNotBlock(t *testing.T) {
131		dir := setupCorruptCompareArchive(t)
132		before := readEnableSkeleton(t, dir)
133		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
134			storedRule(t, ver, "displacement")["multiplier"] = 0
135		})
136		damaged := readEnableSkeleton(t, dir)
137	
138		twin, err := EnableVersion(dir, "twin")
139		if err != nil {
140			t.Fatalf("enabling intact twin past a corrupt sibling failed: %v", err)
141		}
142		if twin.ID != "twin" || twin.Rules.Displacement.Multiplier != 2 {
143			t.Fatalf("enabled twin returned wrong parameters: %+v", twin)
144		}
145		after := readEnableSkeleton(t, dir)
146		if !reflect.DeepEqual(damaged.Versions, after.Versions) {
147			t.Fatalf("successful switch rewrote the versions section:\nbefore=%s\nafter =%s", damaged.Versions, after.Versions)
148		}
149		if after.EnabledVersion != "twin" {
150			t.Fatalf("enabled marker = %q, want twin", after.EnabledVersion)
151		}
152	
153		// Builtin needs no registration and is enableable with the same corrupt
154		// sibling present; its original parameters come back in full.
155		b, err := EnableVersion(dir, BuiltinVersionID)
156		if err != nil {
157			t.Fatalf("enabling builtin past a corrupt sibling failed: %v", err)
158		}
159		if b != BuiltinVersion() {
160			t.Fatalf("builtin parameters wrong: %+v", b)
161		}
162		after = readEnableSkeleton(t, dir)
163		if !reflect.DeepEqual(damaged.Versions, after.Versions) {
164			t.Fatalf("enabling builtin rewrote the versions section")
165		}
166		if after.EnabledVersion != BuiltinVersionID {
167			t.Fatalf("enabled marker = %q, want builtin", after.EnabledVersion)
168		}
169	
170		// The corrupt entry was not repaired: selecting it still fails as
171		// corruption, and the intact twin remains usable.
172		if _, err := EnableVersion(dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
173			t.Fatalf("corrupt sibling was silently repaired: %v", err)
174		}
175		if _, err := EnableVersion(dir, "twin"); err != nil {
176			t.Fatalf("intact twin no longer enableable: %v", err)
177		}
178		// Nothing structural besides the marker ever moved: order and records.
179		if len(after.Versions) != len(before.Versions) {
180			t.Fatalf("version count changed: %d vs %d", len(after.Versions), len(before.Versions))
181		}
182		if !reflect.DeepEqual(before.Records, after.Records) {
183			t.Fatalf("existing records changed on a version switch")
184		}
185	}
186	
187	// TestEnableUnknownVersionDistinct pins the boundary: an id that was never
188	// registered stays an unknown-version failure (never corruption), and the
189	// failure moves no marker.
190	func TestEnableUnknownVersionDistinct(t *testing.T) {
191		dir := setupCorruptCompareArchive(t)
192		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
193			delete(storedRule(t, ver, "displacement"), "multiplier")
194		})
195		before := readArchiveFile(t, dir)
196	
197		if _, err := EnableVersion(dir, "ghost"); !errors.Is(err, ErrUnknownVersion) ||
198			errors.Is(err, ErrCorruptVersion) {
199			t.Fatalf("unknown version error = %v", err)
200		}
201		if _, err := EnableVersion(dir, ""); err == nil {
202			t.Fatal("empty version id must fail")
203		}
204		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
205			t.Fatalf("failed enable changed the archive")
206		}
207		if got := readEnableSkeleton(t, dir).EnabledVersion; got != "" {
208			t.Fatalf("enabled marker changed on unknown-version failure: %q", got)
209		}
210	}
211	
212	// TestEnableExplicitlyDisabledRulesAccepted proves enabled:false is a legal
213	// off state: a version with both rules disabled still has to carry complete
214	// parameters, and enabling it returns the full declaration which then
215	// governs plain (no --version) replays.
216	func TestEnableExplicitlyDisabledRulesAccepted(t *testing.T) {
217		dir := t.TempDir()
218		offSpec := `{"id":"off","rules":{"sandwich":{"enabled":false,"severity":1},"displacement":{"enabled":false,"severity":1,"multiplier":2}}}`
219		register(t, dir, offSpec)
220		v, err := EnableVersion(dir, "off")
221		if err != nil {
222			t.Fatalf("an explicitly disabled version must enable: %v", err)
223		}
224		want := mustRuleVersion(t, offSpec)
225		if !reflect.DeepEqual(v, want) {
226			t.Fatalf("enabled version = %+v, want %+v", v, want)
227		}
228		reports := replay(t, dir, sandwichInput)
229		if len(reports[0].Findings) != 0 || reports[0].Version.ID != "off" {
230			t.Fatalf("plain replay did not use the enabled disabled version: %+v", reports[0])
231		}
232	}
233	
234	// TestEnableCorruptDuplicateFieldRefused covers a decay registration could
235	// never have produced: a repeated field in the stored document. The raw
236	// bytes are patched directly because a JSON map cannot hold two keys.
237	func TestEnableCorruptDuplicateFieldRefused(t *testing.T) {
238		dir := setupCorruptCompareArchive(t)
239		path := filepath.Join(dir, archiveFileName)
240		raw := readArchiveFile(t, dir)
241		text := string(raw)
242		// Records precede the versions array and embed a full copy of candC in
243		// their "version" field, so anchor past "versions": the duplicate must
244		// land in the stored registration document, not in an archived record.
245		vsec := strings.Index(text, `"versions":`)
246		if vsec < 0 {
247			t.Fatal("versions section not found in archive")
248		}
249		at := strings.Index(text[vsec:], `"id": "candC"`)
250		if at < 0 {
251			t.Fatal("candC entry not found in versions section")
252		}
253		at += vsec
254		anchor := `"severity": 4,`
255		field := strings.Index(text[at:], anchor)
256		if field < 0 {
257			t.Fatal("candC severity field not found")
258		}
259		pos := at + field
260		patched := text[:pos] + `"severity": 4, ` + text[pos:]
261		if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
262			t.Fatal(err)
263		}
264		before := readArchiveFile(t, dir)
265	
266		_, err := EnableVersion(dir, "candC")
267		if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
268			t.Fatalf("duplicate-field document: err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
269		}
270		if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
271			t.Fatalf("error must name candC and severity, got %v", err)
272		}
273		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
274			t.Fatalf("refused enable changed the archive")
275		}
276	}
277	
278	// TestEnableCorruptDuplicateIDRefused covers a decayed document that also
279	// repeats its identity key: "id":"other" arrives last and a plain unmarshal
280	// would fold the entry onto "other", hiding candC behind an unknown-version
281	// error. The matcher must still attribute the entry to the registered
282	// version and refuse it as corruption, under either spelling.
283	func TestEnableCorruptDuplicateIDRefused(t *testing.T) {
284		dir := setupCorruptCompareArchive(t)
285		path := filepath.Join(dir, archiveFileName)
286		text := string(readArchiveFile(t, dir))
287		vsec := strings.Index(text, `"versions":`)
288		at := strings.Index(text[vsec:], `"id": "candC"`)
289		if at < 0 {
290			t.Fatal("candC entry not found in versions section")
291		}
292		pos := vsec + at
293		patched := text[:pos] + `"id": "candC", "id": "other", ` + text[pos+len(`"id": "candC",`):]
294		if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
295			t.Fatal(err)
296		}
297		before := readArchiveFile(t, dir)
298	
299		for _, asked := range []string{"candC", "other"} {
300			if _, err := EnableVersion(dir, asked); !errors.Is(err, ErrCorruptVersion) ||
301				errors.Is(err, ErrUnknownVersion) {
302				t.Fatalf("enabling %q against a duplicate-id document: %v", asked, err)
303			}
304		}
305		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
306			t.Fatalf("refused enable changed the archive")
307		}
308		// The intact twin is unaffected by the unidentifiable sibling.
309		if _, err := EnableVersion(dir, "twin"); err != nil {
310			t.Fatalf("intact twin blocked by corrupt sibling: %v", err)
311		}
312	}
313	
314	// TestEnableInvalidAndBusyArchiveReported covers the environment-level
315	// failures: an archive whose whole file is not valid JSON, or one locked by
316	// another process, must error clearly and leave the file alone.
317	func TestEnableInvalidAndBusyArchiveReported(t *testing.T) {
318		dir := t.TempDir()
319		register(t, dir, candidateVersionSpec)
320		path := filepath.Join(dir, archiveFileName)
321		if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
322			t.Fatal(err)
323		}
324		before := readArchiveFile(t, dir)
325		if _, err := EnableVersion(dir, "candC"); err == nil ||
326			errors.Is(err, ErrUnknownVersion) || errors.Is(err, ErrCorruptVersion) {
327			t.Fatalf("invalid-JSON archive error = %v, want a whole-archive corruption error", err)
328		}
329		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
330			t.Fatalf("failed enable rewrote an invalid archive")
331		}
332	
333		// Busy archive: the lock failure is reported as such (fixture from the
334		// registration tests, version absent there so the lock is hit first).
335		busyDir := t.TempDir()
336		lock, err := os.OpenFile(filepath.Join(busyDir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
337		if err != nil {
338			t.Fatal(err)
339		}
340		defer lock.Close()
341		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
342			t.Fatal(err)
343		}
344		if _, err := EnableVersion(busyDir, "candC"); !errors.Is(err, ErrBusy) {
345			t.Fatalf("busy archive error = %v, want ErrBusy", err)
346		}
347	}
348	
349	// TestEnableLegacyArchiveAllowsBuiltin proves pre-version archives (no
350	// versions or enabledVersion fields) can still enable builtin, and the
351	// marker then drives plain replays without touching the legacy record.
352	func TestEnableLegacyArchiveAllowsBuiltin(t *testing.T) {
353		dir := t.TempDir()
354		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
355			`"swaps":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
356			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
357			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
358			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
359			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
360			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
361			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
362		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
363			t.Fatal(err)
364		}
365		b, err := EnableVersion(dir, BuiltinVersionID)
366		if err != nil {
367			t.Fatalf("enabling builtin on a legacy archive failed: %v", err)
368		}
369		if b != BuiltinVersion() {
370			t.Fatalf("builtin parameters wrong: %+v", b)
371		}
372		if got := readEnableSkeleton(t, dir).EnabledVersion; got != BuiltinVersionID {
373			t.Fatalf("enabled marker = %q, want builtin", got)
374		}
375		reports := replay(t, dir, replayCorruptInput)
376		if len(reports) != 1 || reports[0].Version.ID != BuiltinVersionID ||
377			len(reports[0].Findings) != 1 || reports[0].Findings[0].Kind != "displacement" {
378			t.Fatalf("plain replay after enabling builtin misjudged: %+v", reports)
379		}
380		r, err := Query(dir, "1", "0old")
381		if err != nil {
382			t.Fatal(err)
383		}
384		if r.Version != BuiltinVersion() || len(r.Findings) != 1 {
385			t.Fatalf("legacy record modified on switch: %+v", r)
386		}
387	
388		// An empty archive (no file yet) accepts builtin the same way.
389		fresh := t.TempDir()
390		if _, err := EnableVersion(fresh, BuiltinVersionID); err != nil {
391			t.Fatalf("enabling builtin before any archive exists failed: %v", err)
392		}
393	}
394	
395	// TestEnableSwitchPreservesAllPriorState builds an archive holding every
396	// kind of state, then switches to an intact version and proves only the
397	// enabled marker changed: stored versions survive verbatim, and reports,
398	// suppressions, alert processing records and manual reviews keep their
399	// historical conclusions — nothing is re-detected or rewritten.
400	func TestEnableSwitchPreservesAllPriorState(t *testing.T) {
401		dir := t.TempDir()
402		register(t, dir, candidateVersionSpec)
403		register(t, dir, twinVersionSpec)
404		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
405			t.Fatal(err)
406		}
407		if _, err := EnableVersion(dir, "candC"); err != nil {
408			t.Fatal(err)
409		}
410		if _, _, err := RegisterSuppression(dir, []byte(
411			`{"id":"s1","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":1,"endHeight":100,"reason":"r"}`,
412		)); err != nil {
413			t.Fatal(err)
414		}
415		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
416			t.Fatal(err)
417		}
418		if _, err := SubmitReview(dir, ReviewSubmission{
419			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
420			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
421			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
422		}); err != nil {
423			t.Fatal(err)
424		}
425		before := readEnableSkeleton(t, dir)
426	
427		if v, err := EnableVersion(dir, "twin"); err != nil || v.ID != "twin" {
428			t.Fatalf("switch to twin: v=%+v err=%v", v, err)
429		}
430		// Switching to the already-enabled marker semantics: re-enabling twin
431		// now is a no-write validation path and still succeeds.
432		if _, err := EnableVersion(dir, "twin"); err != nil {
433			t.Fatalf("re-enabling the current intact version failed: %v", err)
434		}
435	
436		after := readEnableSkeleton(t, dir)
437		if !reflect.DeepEqual(before.Versions, after.Versions) {
438			t.Fatalf("switch rewrote stored versions:\nbefore=%s\nafter =%s", before.Versions, after.Versions)
439		}
440		if after.EnabledVersion != "twin" {
441			t.Fatalf("enabled marker = %q, want twin", after.EnabledVersion)
442		}
443		if !reflect.DeepEqual(before.Records, after.Records) {
444			t.Fatalf("historical reports changed on switch: %+v vs %+v", before.Records, after.Records)
445		}
446		if !reflect.DeepEqual(before.Suppressions, after.Suppressions) {
447			t.Fatalf("suppressions changed on switch")
448		}
449		if !reflect.DeepEqual(before.AlertRecords, after.AlertRecords) {
450			t.Fatalf("alert records changed on switch")
451		}
452		if !reflect.DeepEqual(before.Reviews, after.Reviews) {
453			t.Fatalf("manual reviews changed on switch")
454		}
455	
456		// Historical conclusions keep their candC verdict and are not re-judged.
457		report, err := Query(dir, "1", "0xa")
458		if err != nil {
459			t.Fatal(err)
460		}
461		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
462			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
463			t.Fatalf("archived report re-detected on switch: %+v", report)
464		}
465		history, err := ReviewHistoryQuery(dir, "1", "0xa", "0xvictim", "displacement")
466		if err != nil {
467			t.Fatal(err)
468		}
469		if history.Status != ReviewStatusFalsePositive || history.Version != 1 {
470			t.Fatalf("review history changed on switch: %+v", history)
471		}
472		alerts, err := AlertHistory(dir, "1", "ops", 0, 100)
473		if err != nil {
474			t.Fatal(err)
475		}
476		if len(alerts) != 1 || alerts[0].Status != AlertStatusSuppressed {
477			t.Fatalf("alert history changed on switch: %+v", alerts)
478		}
479	
480		// A new block without an explicit version is judged under twin now.
481		input := cmpBlockLine("1", "0xnew", 11,
482			cmpSwap("0xn1", "p1", "w", 40, 0),
483			cmpSwap("0xn2", "p1", "u", 10, 1),
484		)
485		reports, err := Replay(strings.NewReader(input), dir)
486		if err != nil {
487			t.Fatal(err)
488		}
489		if len(reports) != 1 || reports[0].Version.ID != "twin" {
490			t.Fatalf("new block did not replay under the newly enabled version: %+v", reports)
491		}
492	}
493

