357				}
358				records, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
359				if err == nil {
360					t.Fatalf("duplicate-field declaration returned history: %+v", records)
361				}
362				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
363					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
364				}
365				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
366					t.Fatalf("error must name candC and severity, got %v", err)
367				}
368				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
369					t.Fatal("failed history repaired the duplicate field")
370				}
371			})
372		}
373	}
374	
375	// TestAlertHistoryDisabledAndUnregisteredDeclarationsAccepted proves a
376	// legal record is used exactly as saved: an explicit enabled:false is a
377	// legal off state as long as the disabled rule keeps complete, in-range
378	// parameters, and the saved id need not still be registered — parameters
379	// are never pulled from the enabled or a same-id registered version.
380	func TestAlertHistoryDisabledAndUnregisteredDeclarationsAccepted(t *testing.T) {
381		off := map[string]any{
382			"id": "off",
383			"rules": map[string]any{
384				"sandwich":     map[string]any{"enabled": false, "severity": 1},
385				"displacement": map[string]any{"enabled": false, "severity": 1, "multiplier": 2},
386			},
387		}
388		dir := setupAlertHistoryCorruptArchive(t)
389		replaceStoredAlertVersion(t, dir,
390			alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel, off)
391		got, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
392		if err != nil {
393			t.Fatalf("an explicitly disabled, complete declaration must query: %v", err)
394		}
395		if len(got) != 1 || got[0].Version.ID != "off" ||
396			got[0].Version.Rules.Sandwich.Enabled || got[0].Version.Rules.Displacement.Enabled {
397			t.Fatalf("saved off state not carried: %+v", got)
398		}
399	
400		// Disabled does not pardon a missing severity: the rule still has to be
401		// declared completely.
402		offBroken := map[string]any{
403			"id": "off",
404			"rules": map[string]any{
405				"sandwich":     map[string]any{"enabled": false},
406				"displacement": map[string]any{"enabled": false, "severity": 1, "multiplier": 2},
407			},
408		}
409		dir = setupAlertHistoryCorruptArchive(t)
410		replaceStoredAlertVersion(t, dir,
411			alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel, offBroken)
412		assertAlertHistoryRefused(t, dir, alertHistoryChain, alertHistoryChannel, 0, 100, "off", "severity")
413	
414		// A complete declaration with an id the registry never carried stands
415		// on its own.
416		ghost := map[string]any{
417			"id": "never-registered",
418			"rules": map[string]any{
419				"sandwich":     map[string]any{"enabled": false, "severity": 1},
420				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 100},
421			},
422		}
423		dir = setupAlertHistoryCorruptArchive(t)
424		replaceStoredAlertVersion(t, dir,
425			alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel, ghost)
426		got, err = AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
427		if err != nil {
428			t.Fatalf("a complete self-contained declaration must not need registry backing: %v", err)
429		}
430		v := got[0].Version
431		if v.ID != "never-registered" || v.Rules.Displacement.Severity != 5 || v.Rules.Displacement.Multiplier != 100 {
432			t.Fatalf("saved parameters not carried: %+v", v)
433		}
434		if _, err := GetVersion(dir, "never-registered"); !errors.Is(err, ErrUnknownVersion) {
435			t.Fatalf("the record-only id must not be taken from the registry: %v", err)
436		}
437	}
438	
439	// TestAlertHistoryProofUsesRecordNotReportOrRegistry proves the proof reads
440	// the record's own declaration: a damaged same-id registry version and a
441	// damaged declaration on the block's own report neither block nor complete
442	// an intact saved record, and the saved id need not be registered.
443	func TestAlertHistoryProofUsesRecordNotReportOrRegistry(t *testing.T) {
444		// Damage the registered candC entry while every saved record stays
445		// intact: the history still shows the record with its own parameters.
446		dir := setupAlertHistoryCorruptArchive(t)
447		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
448			delete(storedRule(t, ver, "displacement"), "multiplier")
449		})
450		got, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
451		if err != nil {
452			t.Fatalf("a corrupt registry sibling must not block an intact alert record: %v", err)
453		}
454		if want := mustRuleVersion(t, candidateVersionSpec); len(got) != 1 || got[0].Version != want {
455			t.Fatalf("history borrowed registry parameters: %+v want %+v", got, want)
456		}
457	
458		// Damage the block report's own embedded declaration while the alert
459		// record stays intact: the history is unaffected and never re-proves or
460		// borrows from the report.
461		dir = setupAlertHistoryCorruptArchive(t)
462		rewriteStoredReportVersion(t, dir, alertHistoryChain, alertHistoryBlock, func(ver map[string]any) {
463			storedRule(t, ver, "displacement")["multiplier"] = 0
464		})
465		got, err = AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
466		if err != nil {
467			t.Fatalf("a corrupt block report must not block an intact alert record: %v", err)
468		}
469		if len(got) != 1 || got[0].Version.Rules.Displacement.Multiplier != 2 {
470			t.Fatalf("alert record parameters must come from the record, not the damaged report: %+v", got)
471		}
472	
473		// Conversely, an intact registry cannot rescue a corrupt record: damage
474		// only the alert record's own copy while the registry stays intact.
475		dir = setupAlertHistoryCorruptArchive(t)
476		rewriteStoredAlertVersion(t, dir,
477			alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel,
478			func(ver map[string]any) {
479				storedRule(t, ver, "displacement")["multiplier"] = 0
480			})
481		assertAlertHistoryRefused(t, dir, alertHistoryChain, alertHistoryChannel, 0, 100, "candC", "multiplier")
482	}
483	
484	// TestAlertHistoryCorruptSiblingDoesNotBlock proves the integrity proof is
485	// scoped to the records the query actually returns: a damaged declaration
486	// on another channel, another chain or outside the height range does not
487	// block the query, while the damaged record fails a query that hits it.
488	func TestAlertHistoryCorruptSiblingDoesNotBlock(t *testing.T) {
489		dir := t.TempDir()
490		// Block 0xa at height 10 on chain 1 with two conclusions; every
491		// conclusion is processed for both ops and audit, and the same block is
492		// archived on chain 2 for ops as well.
493		mustReplay(t, dir, twoFindingsInput)
494		other := strings.Replace(twoFindingsInput, `"chainId":"1"`, `"chainId":"2"`, 1)
495		mustReplay(t, dir, other)
496		for _, ch := range []string{"ops", "audit"} {
497			if _, err := GenerateAlerts(dir, "1", ch, 0, 100, 1); err != nil {
498				t.Fatal(err)
499			}
500		}
501		if _, err := GenerateAlerts(dir, "2", "ops", 0, 100, 1); err != nil {
502			t.Fatal(err)
503		}
504	
505		// Corrupt only the chain-1 ops sandwich record (0xv): the audit copy,
506		// the chain-1 ops displacement copy (0xd), and the chain-2 copies stay
507		// intact.
508		rewriteStoredAlertVersion(t, dir, "1", "0xa", "0xv", SuppressSandwich, "ops", func(ver map[string]any) {
509			storedRule(t, ver, "displacement")["multiplier"] = 0
510		})
511	
512		// Hitting the damaged record fails the whole query — no partial
513		// history, the intact displacement record on the same channel is not
514		// returned either.
515		assertAlertHistoryRefused(t, dir, "1", "ops", 0, 100, "1", "0xa", "0xv", SuppressSandwich, "ops")
516	
517		// The other channel's identical conclusions stay queryable.
518		audit, err := AlertHistory(dir, "1", "audit", 0, 100)
519		if err != nil {
520			t.Fatalf("other channel must stay queryable: %v", err)
521		}
522		if len(audit) != 2 {
523			t.Fatalf("audit history = %+v, want both conclusions", audit)
524		}
525	
526		// The other chain's records stay queryable.
527		chain2, err := AlertHistory(dir, "2", "ops", 0, 100)
528		if err != nil {
529			t.Fatalf("other chain must stay queryable: %v", err)
530		}
531		if len(chain2) != 2 {
532			t.Fatalf("chain 2 history = %+v, want both conclusions", chain2)
533		}
534	
535		// A range that excludes height 10 never opens the damaged record.
536		above, err := AlertHistory(dir, "1", "ops", 11, 100)
537		if err != nil {
538			t.Fatalf("out-of-range query must not open the damaged record: %v", err)
539		}
540		if len(above) != 0 {
541			t.Fatalf("out-of-range history = %+v, want []", above)
542		}
543	
544		// The damaged record still fails under every scope that includes it,
545		// and the corrupt declaration is written back verbatim.
546		if _, err := AlertHistory(dir, "1", "ops", 10, 10); !errors.Is(err, ErrCorruptVersion) {
547			t.Fatalf("inclusive single-height query must fail: %v", err)
548		}
549		if !strings.Contains(string(readArchiveFile(t, dir)), `"multiplier": 0`) {
550			t.Fatal("failed history query repaired the corrupt record")
551		}
552	}
553	
554	// TestAlertHistorySuccessContentAndOrderPreserved proves healthy records
555	// keep their full JSON content — conclusion, swap evidence, generation
556	// threshold, suppression hits, saved parameters — in the height, block
557	// hash, tx hash and kind ascending order generation uses, with [] for an
558	// empty result.
559	func TestAlertHistorySuccessContentAndOrderPreserved(t *testing.T) {
560		dir := setupSuppressedAlertHistoryArchive(t)
561		got, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 7, 7)
562		if err != nil {
563			t.Fatal(err)
564		}
565		if len(got) != 1 {
566			t.Fatalf("got %+v, want one record", got)
567		}
568		r := got[0]
569		if r.ChainID != alertHistoryChain || r.BlockHash != alertHistoryBlock || r.BlockNumber != 7 ||
570			r.Channel != alertHistoryChannel || r.Pool != "p1" {
571			t.Fatalf("identity wrong: %+v", r)
572		}
573		if r.Finding.Kind != alertHistoryKind || r.Finding.TxHash != alertHistoryTx ||
574			r.Finding.Severity != 4 || len(r.Finding.Evidence) != 2 {
575			t.Fatalf("conclusion/evidence wrong: %+v", r.Finding)
576		}
577		if r.MinSeverity != 1 || r.Status != AlertStatusSuppressed {
578			t.Fatalf("threshold/status wrong: %+v", r)
579		}
580		if len(r.Suppressions) != 1 || r.Suppressions[0].ID != "s1" ||
581			r.Suppressions[0].Reason != "known bot war" {
582			t.Fatalf("suppression hits wrong: %+v", r.Suppressions)
583		}
584		if want := mustRuleVersion(t, candidateVersionSpec); r.Version != want {
585			t.Fatalf("saved detection version wrong: %+v want %+v", r.Version, want)
586		}
587	
588		// Deterministic across reads, no re-detection.
589		again, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
590		if err != nil {
591			t.Fatal(err)
592		}
593		if !reflect.DeepEqual(got, again) {
594			t.Fatalf("repeated query differs:\n%+v\n%+v", got, again)
595		}
596	
597		// Ordering matches generation's height/hash/tx/kind order on a
598		// multi-block archive.
599		dir2 := t.TempDir()
600		mustReplay(t, dir2, `{"chainId":"1","blockHash":"0xc","blockNumber":1,"swaps":[`+
601			`{"TxHash":"0xf1","Pool":"p1","Trader":"b","In":1,"Out":1,"GasPrice":90,"Index":0},`+
602			`{"TxHash":"0+h1","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},`+
603			`{"TxHash":"0+z1","Pool":"p1","Trader":"b","In":1,"Out":1,"GasPrice":80,"Index":2}]}`)
604		mustReplay(t, dir2, twoFindingsInput) // 0xa at height 10
605		created, err := GenerateAlerts(dir2, "1", "ops", 0, 100, 1)
606		if err != nil {
607			t.Fatal(err)
608		}
609		hist, err := AlertHistory(dir2, "1", "ops", 0, 100)
610		if err != nil {
611			t.Fatal(err)
612		}
613		if !reflect.DeepEqual(hist, created) {
614			t.Fatalf("history order/content differs from generation:\n%+v\n%+v", hist, created)
615		}
616	}
617	
618	// TestAlertHistoryEmptyAndOldArchives proves the empty shapes stay empty:
619	// a missing directory, an old-format archive without an alerts section, an
620	// explicit empty alerts array and a range with no matching record all
621	// return []; none of them is reinterpreted using a missing declaration.
622	func TestAlertHistoryEmptyAndOldArchives(t *testing.T) {
623		emptyCases := func(t *testing.T, dir string) {
624			t.Helper()
625			for _, scope := range []struct {
626				chain, channel string
627				start, end     uint64
628			}{
629				{"1", "ops", 0, 100},
630				{"2", "ops", 0, 100},
631				{"1", "audit", 0, 100},
632				{"1", "ops", 100, 200},
633			} {
634				got, err := AlertHistory(dir, scope.chain, scope.channel, scope.start, scope.end)
635				if err != nil {
636					t.Fatalf("scope %+v: %v", scope, err)
637				}
638				raw, _ := json.Marshal(got)
639				if string(raw) != "[]" {
640					t.Fatalf("scope %+v = %s, want []", scope, raw)
641				}
642			}
643		}
644	
645		t.Run("missing directory", func(t *testing.T) {
646			emptyCases(t, filepath.Join(t.TempDir(), "absent"))
647		})
648	
649		t.Run("old archive without alerts section", func(t *testing.T) {
650			dir := t.TempDir()
651			data := archiveData{Records: []record{{
652				ChainID: "1", BlockHash: "0old", BlockNumber: 5,
653				Findings: []ReportFinding{{Kind: "sandwich", Severity: 3, TxHash: "0v"}},
654			}}}
655			if err := writeArchiveAtomic(dir, data); err != nil {
656				t.Fatal(err)
657			}
658			emptyCases(t, dir)
659			text := string(readArchiveFile(t, dir))
660			if strings.Contains(text, "alerts") {
661				t.Fatalf("old archive must carry no alerts section: %s", text)
662			}
663		})
664	
665		t.Run("explicit empty alerts array", func(t *testing.T) {
666			dir := setupAlertHistoryCorruptArchive(t)
667			editStoredAlert(t, dir,
668				alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel,
669				func(rec map[string]any) {})
670			// Remove every alert entry by rewriting the section wholesale.
671			path := filepath.Join(dir, archiveFileName)
672			raw, _ := os.ReadFile(path)
673			var doc map[string]any
674			if err := json.Unmarshal(raw, &doc); err != nil {
675				t.Fatal(err)
676			}
677			doc["alerts"] = []any{}
678			out, _ := json.MarshalIndent(doc, "", "  ")
679			if err := os.WriteFile(path, out, 0o644); err != nil {
680				t.Fatal(err)
681			}
682			emptyCases(t, dir)
683		})
684	}
685	
686	// TestAlertHistoryCorruptedArchiveFailsClearly proves a wholly unreadable
687	// archive is still an archive-corruption error, never [] or a version
688	// error, and the failed query does not rewrite the file.
689	func TestAlertHistoryCorruptedArchiveFailsClearly(t *testing.T) {
690		dir := setupAlertHistoryCorruptArchive(t)
691		corrupt := []byte("{not json")
692		if err := os.WriteFile(filepath.Join(dir, archiveFileName), corrupt, 0o644); err != nil {
693			t.Fatal(err)
694		}
695		records, err := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
696		if err == nil || !strings.Contains(err.Error(), "corrupted") {
697			t.Fatalf("got %v / %+v, want corrupted-archive error", err, records)
698		}
699		if errors.Is(err, ErrCorruptVersion) {
700			t.Fatalf("whole-archive JSON damage must not masquerade as one record's corrupt version: %v", err)
701		}
702		if after, rerr := os.ReadFile(filepath.Join(dir, archiveFileName)); rerr != nil || !reflect.DeepEqual(after, corrupt) {
703			t.Fatalf("failed query changed the archive: %q %v", after, rerr)
704		}
705	}
