func TestZZReproRegisterRewritesCorruptAlert(t *testing.T) {
	dir := setupAlertHistoryCorruptArchive(t)
	replaceStoredAlertVersion(t, dir,
		alertHistoryChain, alertHistoryBlock, alertHistoryTx, alertHistoryKind, alertHistoryChannel, nil)
	t.Logf("before:\n%s", string(readArchiveFile(t, dir)))
	spec := `{"id":"s9","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":100,"endHeight":200,"reason":"r"}`
	cond, created, err := RegisterSuppression(dir, []byte(spec))
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("registered created=%v cond=%+v", created, cond)
	after := string(readArchiveFile(t, dir))
	t.Logf("after:\n%s", after)
	if strings.Contains(after, `"version": null`) {
		t.Logf("null survived")
	} else {
		t.Logf("NULL WAS REWRITTEN")
	}
	_ = os.Remove
	_ = filepath.Join
}

