22	// saved processing record's version declaration to value, simulating
23	// on-disk decay a JSON round-trip through the API could not produce.
24	func corruptCLIAlertVersion(t *testing.T, dir, tx, kind, channel string, edit func(ver map[string]any)) {
25		t.Helper()
26		path := filepath.Join(dir, "archive.json")
27		raw, err := os.ReadFile(path)
